#include <bits/stdc++.h>
using namespace std;

#define mp make_pair
#define all(x) (x).begin(), (x).end()
#define sz(x) ((int)(x).size())
#define fi first
#define se second
typedef long long ll;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
const int N = 12, INF = 1000000009;
const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

struct Point {
    int x, y;
    Point() {}
    Point(int _x, int _y) : x(_x), y(_y) {}
};

int n, t;
char gridA[N][N], gridB[N][N];

int startX, startY;
int dist[N][N];

void perform_bfs(int dist_map[N][N], int sx, int sy) {
    bool visited[N][N] = {};
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dist_map[i][j] = INF;
    queue<Point> q;
    visited[sx][sy] = true;
    dist_map[sx][sy] = 0;
    q.push(Point(sx, sy));
    while (!q.empty()) {
        Point curr = q.front(); q.pop();
        for (int dir = 0; dir < 4; ++dir) {
            Point next_point = curr;
            next_point.x += dx[dir];
            next_point.y += dy[dir];
            if (next_point.x >= 0 && next_point.x < n && next_point.y >= 0 && next_point.y < n
                && !visited[next_point.x][next_point.y] && gridA[next_point.x][next_point.y] >= '0'
                && gridA[next_point.x][next_point.y] <= '9') {
                visited[next_point.x][next_point.y] = true;
                dist_map[next_point.x][next_point.y] = dist_map[curr.x][curr.y] + 1;
                q.push(next_point);
            }
        }
    }
}

bool flow[N * 6][N][N][N][N];
bool reachable[N][N][N][N];

int graph[2 * N * N][2 * N * N];

int parent[2 * N * N];
bool visited_flow[2 * N * N];

bool bfs_for_flow() {
    memset(visited_flow, false, sizeof(visited_flow));
    memset(parent, 0, sizeof(parent));
    queue<int> q;
    visited_flow[0] = true;
    q.push(0);
    while (!q.empty()) {
        int node = q.front(); q.pop();
        if (node == 2 * n * n + 1)
            return true;
        for (int h = 0; h <= 2 * n * n + 1; ++h) {
            if (graph[node][h]) {
                if (!visited_flow[h]) {
                    visited_flow[h] = true;
                    parent[h] = node;
                    q.push(h);
                }
            }
        }
    }
    return false;
}

void solve() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i)
        scanf(" %s", gridA[i]);
    for (int i = 0; i < n; ++i)
        scanf(" %s", gridB[i]);
    scanf("%d%d", &startX, &startY);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (gridA[i][j] == 'Z') {
                startX = i; startY = j;
            }

    perform_bfs(dist, startX, startY);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if ('0' <= gridA[i][j] && gridA[i][j] <= '9')
                flow[0][i][j][i][j] = true;

    for (int step = 0; step < t; ++step) {
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y) {
                        if (!flow[step][sx][sy][x][y]) continue;
                        if (dist[x][y] <= step) continue;
                        for (int dir = 0; dir < 4; ++dir) {
                            int hx = x + dx[dir];
                            int hy = y + dy[dir];
                            if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= gridA[hx][hy] && gridA[hx][hy] <= '9') {
                                if (dist[hx][hy] >= step + 1)
                                    flow[step + 1][sx][sy][hx][hy] = true;
                            }
                        }
                    }
    }

    for (int step = 0; step <= t; ++step)
        for (int sx = 0; sx < n; ++sx)
            for (int sy = 0; sy < n; ++sy)
                for (int x = 0; x < n; ++x)
                    for (int y = 0; y < n; ++y)
                        if (flow[step][sx][sy][x][y])
                            reachable[sx][sy][x][y] = true;

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            if ('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')
                graph[0][x1 * n + y1 + 1] = gridA[x1][y1] - '0';

    for (int x2 = 0; x2 < n; ++x2)
        for (int y2 = 0; y2 < n; ++y2)
            if ('0' <= gridB[x2][y2] && gridB[x2][y2] <= '9')
                graph[n * n + x2 * n + y2 + 1][2 * n * n + 1] = gridB[x2][y2] - '0';

    for (int x1 = 0; x1 < n; ++x1)
        for (int y1 = 0; y1 < n; ++y1)
            for (int x2 = 0; x2 < n; ++x2)
                for (int y2 = 0; y2 < n; ++y2) {
                    if (!('0' <= gridA[x1][y1] && gridA[x1][y1] <= '9')) continue;
                    if (!('0' <= gridA[x2][y2] && gridA[x2][y2] <= '9')) continue;
                    if (!reachable[x1][y1][x2][y2]) continue;
                    graph[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                }

    while (bfs_for_flow()) {
        int min_flow = INF;
        for (int i = 2 * n * n + 1; i; i = parent[i]) {
            min_flow = min(min_flow, graph[parent[i]][i]);
        }
        for (int i = 2 * n * n + 1; i; i = parent[i]) {
            graph[parent[i]][i] -= min_flow;
            graph[i][parent[i]] += min_flow;
        }
    }

    int total_flow = 0;
    for (int i = 0; i <= 2 * n * n + 1; ++i)
        total_flow += graph[i][0];

    printf("%d\n", total_flow);
}

int main() {
    #ifdef SOMETHING
    freopen("input.txt", "r", stdin);
    #endif
    solve();
    return 0;
}
